"""A small, dependency-free library-loan ledger used as benign code text.

The module favors explicit state transitions. It is not connected to a network,
database, payment system, or real patron data.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date, timedelta
from enum import Enum
from typing import Iterable


class LoanState(str, Enum):
    AVAILABLE = "available"
    CHECKED_OUT = "checked_out"
    LOST = "lost"


@dataclass(frozen=True)
class Book:
    copy_id: str
    title: str

    def __post_init__(self) -> None:
        if not self.copy_id.strip():
            raise ValueError("copy_id must not be blank")
        if not self.title.strip():
            raise ValueError("title must not be blank")


@dataclass(frozen=True)
class Loan:
    copy_id: str
    patron_id: str
    borrowed_on: date
    due_on: date
    returned_on: date | None = None

    def __post_init__(self) -> None:
        if self.due_on < self.borrowed_on:
            raise ValueError("due date precedes borrowing date")
        if self.returned_on is not None and self.returned_on < self.borrowed_on:
            raise ValueError("return date precedes borrowing date")

    @property
    def active(self) -> bool:
        return self.returned_on is None

    def is_overdue_on(self, day: date) -> bool:
        return self.active and day > self.due_on


class Ledger:
    def __init__(self, books: Iterable[Book], loan_days: int = 21) -> None:
        if loan_days <= 0:
            raise ValueError("loan_days must be positive")
        indexed = {book.copy_id: book for book in books}
        if len(indexed) != len(list(indexed.values())):
            raise ValueError("duplicate copy ID")
        self._books = indexed
        self._loan_days = loan_days
        self._loans: list[Loan] = []
        self._lost: set[str] = set()

    def state(self, copy_id: str) -> LoanState:
        self._require_book(copy_id)
        if copy_id in self._lost:
            return LoanState.LOST
        if self._active_loan(copy_id) is not None:
            return LoanState.CHECKED_OUT
        return LoanState.AVAILABLE

    def borrow(self, copy_id: str, patron_id: str, day: date) -> Loan:
        self._require_book(copy_id)
        if not patron_id.strip():
            raise ValueError("patron_id must not be blank")
        current = self.state(copy_id)
        if current is not LoanState.AVAILABLE:
            raise ValueError(f"copy {copy_id} is {current.value}")
        loan = Loan(copy_id, patron_id, day, day + timedelta(days=self._loan_days))
        self._loans.append(loan)
        return loan

    def return_copy(self, copy_id: str, day: date) -> Loan:
        loan = self._active_loan(copy_id)
        if loan is None:
            raise ValueError(f"copy {copy_id} has no active loan")
        completed = Loan(
            copy_id=loan.copy_id,
            patron_id=loan.patron_id,
            borrowed_on=loan.borrowed_on,
            due_on=loan.due_on,
            returned_on=day,
        )
        position = self._loans.index(loan)
        self._loans[position] = completed
        return completed

    def mark_lost(self, copy_id: str) -> None:
        self._require_book(copy_id)
        if self._active_loan(copy_id) is None:
            raise ValueError("only a checked-out copy can be marked lost")
        self._lost.add(copy_id)

    def restore_lost(self, copy_id: str, returned_on: date) -> Loan:
        if copy_id not in self._lost:
            raise ValueError("copy is not marked lost")
        self._lost.remove(copy_id)
        return self.return_copy(copy_id, returned_on)

    def overdue(self, day: date) -> list[Loan]:
        return sorted(
            (loan for loan in self._loans if loan.is_overdue_on(day)),
            key=lambda loan: (loan.due_on, loan.copy_id),
        )

    def history(self, copy_id: str) -> tuple[Loan, ...]:
        self._require_book(copy_id)
        return tuple(loan for loan in self._loans if loan.copy_id == copy_id)

    def _require_book(self, copy_id: str) -> Book:
        try:
            return self._books[copy_id]
        except KeyError as exc:
            raise KeyError(f"unknown copy ID: {copy_id}") from exc

    def _active_loan(self, copy_id: str) -> Loan | None:
        return next(
            (loan for loan in reversed(self._loans) if loan.copy_id == copy_id and loan.active),
            None,
        )


def demo() -> dict[str, object]:
    books = [
        Book("A-001", "The North Window"),
        Book("A-002", "A Small Atlas"),
        Book("B-010", "Gardens in Winter"),
    ]
    ledger = Ledger(books, loan_days=14)
    first = ledger.borrow("A-001", "reader-7", date(2030, 1, 2))
    second = ledger.borrow("A-002", "reader-9", date(2030, 1, 4))
    assert first.due_on == date(2030, 1, 16)
    assert second.due_on == date(2030, 1, 18)
    assert ledger.state("A-001") is LoanState.CHECKED_OUT
    completed = ledger.return_copy("A-001", date(2030, 1, 10))
    assert completed.returned_on == date(2030, 1, 10)
    assert ledger.state("A-001") is LoanState.AVAILABLE
    assert ledger.overdue(date(2030, 1, 19)) == [second]
    return {
        "available": [copy_id for copy_id in ("A-001", "B-010") if ledger.state(copy_id) is LoanState.AVAILABLE],
        "overdue": [loan.copy_id for loan in ledger.overdue(date(2030, 1, 19))],
    }


def test_borrow_and_return() -> None:
    ledger = Ledger([Book("C-1", "Cloud Notes")], loan_days=7)
    loan = ledger.borrow("C-1", "p-1", date(2031, 5, 1))
    assert loan.due_on == date(2031, 5, 8)
    assert loan.is_overdue_on(date(2031, 5, 9))
    returned = ledger.return_copy("C-1", date(2031, 5, 9))
    assert not returned.is_overdue_on(date(2031, 5, 10))
    assert len(ledger.history("C-1")) == 1


def test_invalid_transitions() -> None:
    ledger = Ledger([Book("D-2", "River Index")])
    try:
        ledger.return_copy("D-2", date(2032, 2, 2))
    except ValueError as exc:
        assert "no active loan" in str(exc)
    else:
        raise AssertionError("returning an available copy must fail")
    ledger.borrow("D-2", "p-2", date(2032, 2, 2))
    try:
        ledger.borrow("D-2", "p-3", date(2032, 2, 3))
    except ValueError as exc:
        assert "checked_out" in str(exc)
    else:
        raise AssertionError("double borrowing must fail")


def test_lost_then_restored() -> None:
    ledger = Ledger([Book("E-3", "Quiet Machines")], loan_days=10)
    ledger.borrow("E-3", "p-4", date(2033, 6, 1))
    ledger.mark_lost("E-3")
    assert ledger.state("E-3") is LoanState.LOST
    restored = ledger.restore_lost("E-3", date(2033, 6, 20))
    assert restored.returned_on == date(2033, 6, 20)
    assert ledger.state("E-3") is LoanState.AVAILABLE


if __name__ == "__main__":
    print(demo())
